static void man_client_auth ( struct management * man , const char * cid_str , const char * kid_str , const bool extra ) { struct man_connection * mc = & man -> connection ; mc -> in_extra_kid = 0 ; if ( parse_cid ( cid_str , & mc -> in_extra_cid ) && parse_uint ( kid_str , "KID" , & mc -> in_extra_kid ) ) { mc -> in_extra_cmd = IEC_CLIENT_AUTH ; in_extra_reset ( mc , IER_NEW ) ; if ( ! extra ) { in_extra_dispatch ( man ) ; } } } 